"""Vast library wrapper for SkyPilot."""
from pathlib import Path
import shlex
from typing import Any, Dict, List, Optional

from sky import sky_logging
from sky.adaptors import vast

logger = sky_logging.init_logger(__name__)

# The SDK's search_offers silently prepends its own default filter
# (verified=true external=false rentable=true rented=false) unless
# no_default=True. Vast does not set `verified` on Secure-Cloud datacenter
# offers (verified=None on every live RTX PRO 6000 Max-Q, measured
# 2026-10-01: the defaulted search returned 4 offers, the same query with
# no_default returned 16 incl. the Max-Q), so the default hid the one
# rentable KVM GPU this lane serves. Every search passes no_default=True and
# states the remaining three terms explicitly; datacenter=true +
# hosting_type>=1 are the lane's trust filter.
SEARCH_BASE_TERMS = 'rentable=true rented=false external=false'

# Vast boots a KVM VM only for images from this repository
# (docs.vast.ai/guides/instances/virtual-machines); every other image is a
# Docker container.
VM_IMAGE_REPO = 'docker.io/vastai/kvm'

# HOST-LEVEL distrust for launch-time offer selection (ENG-493 runs 3-4):
# Vast machine ids whose offers go dark before the bootstrap ever runs.
# The controller prices catalog BUCKETS (one row per gpu/count/ram
# bundle), so a bucket-level refusal there would block every future
# healthy host in the bundle; the machine id is only visible here, at the
# offer level, which is where the blocklist stays. launch() filters these
# hosts out after the search, fail-closed: a bucket whose only offers are
# dead hosts refuses rather than launching one.
_DEAD_ON_ARRIVAL_HOSTS = frozenset({
    # The RTX PRO 6000 WS host: created instances 53903136 (run 4) and
    # 53876457's sibling attempt went 'offline' with the port mapping gone
    # before any bootstrap stage stamped, twice in a row, while the host
    # kept cycling through renters. Not a pin -- remove the id
    # deliberately when the host is demonstrably healthy.
    152941,
})


def is_vm_image(image: Optional[str]) -> bool:
    """Whether `image` makes Vast boot a KVM VM instead of a container."""
    name = str(image or '').strip()
    if name.startswith('docker:'):
        name = name[len('docker:'):]
    return (name == VM_IMAGE_REPO or name.startswith(VM_IMAGE_REPO + ':') or
            name.startswith('vastai/kvm:'))


def list_instances() -> Dict[str, Dict[str, Any]]:
    """Lists instances associated with API key."""
    instances = vast.vast().show_instances()

    instance_dict: Dict[str, Dict[str, Any]] = {}
    for instance in instances:
        instance['id'] = str(instance['id'])
        info = instance

        if isinstance(instance['actual_status'], str):
            info['status'] = instance['actual_status'].upper()
        else:
            info['status'] = 'UNKNOWN'
        info['name'] = instance['label']

        instance_dict[instance['id']] = info

    return instance_dict


def launch(name: str,
           instance_type: str,
           region: str,
           disk_size: int,
           image_name: str,
           ports: Optional[List[int]],
           preemptible: bool,
           secure_only: bool,
           private_docker_registry: Optional[bool] = None,
           login: Optional[str] = None,
           create_instance_kwargs: Optional[Dict[str, Any]] = None,
           ssh_public_key: Optional[str] = None) -> str:
    """Launches an instance with the given parameters.

    Converts the instance_type to the Vast GPU name, finds the specs for the
    GPU, and launches the instance. User-provided parameters in
    create_instance_kwargs are passed through to the Vast API, allowing full
    access to Vast's instance creation options.

    Supported Vast API parameters (via create_instance_kwargs):
      - image: Docker image to use
      - env: Environment variables (e.g., "-e KEY=value -p 8080:8080")
      - price/bid_price: Bid price for the instance
      - disk: Disk size in GB
      - label: Instance label
      - extra: Extra docker run arguments
      - onstart_cmd: Command to run on instance start
      - onstart: Path to a local script file to run on start
      - login: Docker registry login (e.g., "-u user -p pass registry")
      - python_utf8: Enable Python UTF-8 mode
      - lang_utf8: Enable system UTF-8 locale
      - jupyter_lab: Use JupyterLab instead of Jupyter
      - jupyter_dir: Jupyter notebook directory
      - force: Force creation even if warnings
      - cancel_unavail: Cancel if unavailable
      - template_hash/template_hash_id: Use a template
      - args: Custom docker command arguments as list of strings
      - user: Run as specific user

    Notes:
      *  `georegion`: This is a feature flag to provide an additional
         scope of geographical specificy while maintaining backward
         compatibility.
      *  `chunked`: This is a feature flag to give breadth to the
         snowflake nature of the vast catalog marketplace. It rounds
         down various specifications of machines to emulate an instance
         type and make them more interchangeable.
      *  `disk_size`: We look for instances that are of the requested
         size or greater than it. For instance, `disk_size=100` might
         return something with `disk_size` at 102 or even 1000.
         The disk size {xx} GB is not exactly matched the requested
         size {yy} GB. It is possible to charge extra cost on disk.
      *  `ports`: This is a feature flag to expose ports to the internet.
      *  `geolocation`: Geolocation on Vast can be as specific as the
         host chooses to be. They can say, for instance, "Yutakachō,
         Shinagawa District, Tokyo, JP." Such a specific geolocation
         as ours would fail to return this host in a simple string
         comparison if a user searched for "JP".
         Since regardless of specificity, all our geolocations end
         in two-letter country codes we just snip that to conform
         to how many providers state their geolocation.
      *  Since the catalog is cached, we can't gaurantee availability
         of any machine at the point of inquiry.  As a consequence we
         search for the machine again and potentially return a failure
         if there is no availability.
	  *  We pass in the cpu_ram here as a guarantor to make sure the
		 instance we match with will be compliant with the requested
		 amount of memory.
      *  Vast instance types are an invention for skypilot. Refer to
         catalog/vast_catalog.py for the current construction
         of the type.
    """
    # Vast.ai SDK v6+ no longer accepts port mappings via the env field, so
    # `ports` is currently unused. Keep it in the signature for caller
    # compatibility and future use (port-forwarding is handled separately).
    del ports
    # uRun lane requirements: on-demand KVM VMs only (never the plain
    # unprivileged container offers), CUDA-13 capable driver for the cu130
    # wheels, contracts lasting at least 3 days, direct SSH ports for the
    # SkyPilot provision loop, >=96 GB host RAM for the qwen3.6-27b bf16
    # boot, and Secure Cloud datacenters only.
    if not secure_only:
        raise RuntimeError(
            'Vast launches must set sky config vast.datacenter_only=true '
            '(Secure Cloud); community hosts can read the instance disk')
    # Instance type is '{n}x-{gpu_name}-{cpu_cores}-{cpu_ram}' with spaces in
    # gpu_name stubbed to '_' (fetch_vast.create_instance_type). gpu_name may
    # itself contain '-' ('RTX PRO 6000 Max-Q'), so only the first and last
    # two fields are fixed.
    type_fields = instance_type.split('-')
    num_gpus = int(type_fields[0].replace('x', ''))
    gpu_name = '-'.join(type_fields[1:-2]).replace('_', ' ')
    cpu_ram = float(type_fields[-1])

    query = [
        'chunked=true',
        'georegion=true',
        'type=ondemand',
        # 'vm=true' REMOVED: the bundles API rejects `vm` as a search key
        # (measured 2026-09-29: HTTP 400 "vm is not a valid search key").
        # The server-side KVM filter is vms_enabled (measured: 200 with
        # {"vms_enabled":{"eq":True}}); the per-offer `vm` field is not
        # filterable. Keeping vm=true 400s EVERY launch query.
        'vms_enabled=true',
        # NO geolocation TERM: the API exact-matches it against the full
        # "Country, CC, GEO" string, so geolocation="EU" matches NOTHING
        # (measured 2026-09-30: the live launch refused "Failed acquire
        # resources in all zones in EU" while the EU offer was present).
        # Region is filtered client-side after the search (below).
        # UNITS: the SDK's parse_query scales cpu_ram/gpu_ram by 1000 (GB)
        # and duration by 86400 (days) before sending (vastai offers_mult),
        # so terms are written in GB and days. Raw API units here asked for
        # cpu_ram>=65536 GB and duration>=259200 days, matching nothing
        # (measured 2026-10-01: the lane's full query returned 0 offers;
        # in GB/days it returned the live CZ RTX PRO 6000 Max-Q).
        f'disk_space>={disk_size}',
        f'num_gpus={num_gpus}',
        f'gpu_name="{gpu_name}"',
        # Host-RAM floor: the instance type's own RAM (catalog MB -> GB),
        # never below 64 GB — enough for the VM bootstrap (docker +
        # tailscale + juicefs + KV-cache headroom for a 27B bf16 GPU
        # server). The previous 96 GB invention excluded the only
        # affordable Secure-Cloud KVM RTX 6000D offer (94.4 GB) measured
        # 2026-09-29.
        f'cpu_ram>={max(64.0, cpu_ram / 1024):g}',
        'cuda_max_good>=13.0',
        # Contract lasts at least 3 days.
        'duration>=3',
        'direct_port_count>=1',
    ]
    if secure_only:
        query.append('datacenter=true')
        query.append('hosting_type>=1')
    query_str = ' '.join([SEARCH_BASE_TERMS] + query)

    instance_list = vast.vast().search_offers(query=query_str, no_default=True)

    # REGION IS FILTERED CLIENT-SIDE, NOT IN THE QUERY: the API exact-matches
    # geolocation against the full "Country, CC, GEO" string, so
    # geolocation="EU" matches NOTHING (measured 2026-09-30: the live launch
    # refused "Failed acquire resources in all zones in EU" while the EU
    # offer was present — the same full-string-vs-token mismatch the
    # catalog fetcher's Region emission hit). The catalog's Region IS the
    # trailing georegion token (fetch_vast.py), so filter each offer's
    # geolocation trailing token against it.
    region_token = str(region or '').split(',')[-1].strip()
    if region_token:
        instance_list = [
            offer for offer in instance_list
            if str(offer.get('geolocation') or '').split(',')[-1].strip()
            == region_token
        ]
    # Same client-side treatment as the region token above: drop offers
    # from the dead-on-arrival hosts (_DEAD_ON_ARRIVAL_HOSTS, ENG-493
    # runs 3-4) BEFORE the empty check, so a bucket whose only offers are
    # dead hosts refuses here instead of renting one. Host-scoped on
    # purpose: a healthy host in the same bucket still launches.
    instance_list = [
        offer for offer in instance_list
        if offer.get('machine_id') not in _DEAD_ON_ARRIVAL_HOSTS
    ]

    if isinstance(instance_list, int) or len(instance_list) == 0:
        raise RuntimeError('Failed to create instances, could not find an '
                           'offer that satisfies the requirements '
                           f'"{query_str}".')

    instance_touse = instance_list[0]

    # Start with user-provided kwargs as the base
    launch_params: Dict[str, Any] = dict(create_instance_kwargs or {})
    # Remove None values to avoid overriding defaults
    launch_params = {k: v for k, v in launch_params.items() if v is not None}

    # Required skypilot parameters
    launch_params['id'] = instance_touse['id']
    # Use user's label if provided, otherwise use skypilot name
    if 'label' not in launch_params:
        launch_params['label'] = name

    # Handle template - normalize both key names
    template_hash_id = launch_params.pop('template_hash_id', None)
    if template_hash_id is None:
        template_hash_id = launch_params.pop('template_hash', None)
    use_template = template_hash_id is not None

    if use_template:
        launch_params['template_hash'] = template_hash_id
        launch_params['template_hash_id'] = template_hash_id

    # Handle image - user can override, but required if no template
    if 'image' not in launch_params and not use_template:
        launch_params['image'] = image_name

    # Handle disk - user can override
    if 'disk' not in launch_params and not use_template:
        launch_params['disk'] = disk_size

    # Handle login - from function arg or user kwargs
    if login and 'login' not in launch_params:
        launch_params['login'] = login
    if private_docker_registry and 'login' not in launch_params:
        raise RuntimeError(
            'Private docker registry requested but no login credentials '
            'were provided.')

    # Vast interruptible capacity is bid/price based and stops (billing disk)
    # when outbid. The uRun Vast lane is destroy-only and on-demand-only.
    if preemptible:
        raise RuntimeError('Vast interruptible instances are not supported; use on-demand capacity')
    if 'bid_price' in launch_params or 'price' in launch_params:
        raise RuntimeError('Vast on-demand launches must not pass price/bid_price')

    # Handle onstart_cmd - read from file if onstart path provided
    user_onstart_cmd = launch_params.pop('onstart_cmd', None)
    onstart_path = launch_params.pop('onstart', None)
    if onstart_path is not None:
        try:
            onstart_from_file = Path(onstart_path).read_text(encoding='utf-8')
        except OSError as e:
            raise RuntimeError(
                f'Failed to read onstart script {onstart_path}: {e}') from e
        if user_onstart_cmd:
            user_onstart_cmd = f'{user_onstart_cmd};{onstart_from_file}'
        else:
            user_onstart_cmd = onstart_from_file

    # Build onstart command - always prepend skypilot requirements
    # These commands are critical for SkyPilot operation and must always run,
    # even when using a template
    skypilot_onstart = [
        'touch ~/.no_auto_tmux',
    ]

    # Inject SSH public key into authorized_keys if provided
    if ssh_public_key:
        # Add commands to inject SSH key into authorized_keys
        skypilot_onstart.extend([
            'mkdir -p ~/.ssh',
            'chmod 700 ~/.ssh',
            # Add a newline first to ensure keys are on separate lines
            'echo "" >> ~/.ssh/authorized_keys',
            (f'echo {shlex.quote(ssh_public_key.strip())} >> '
             '~/.ssh/authorized_keys'),
            'chmod 600 ~/.ssh/authorized_keys',
        ])
        logger.debug('Added SSH key injection to onstart_cmd')

    if user_onstart_cmd:
        skypilot_onstart.append(user_onstart_cmd)
    # KVM VM images (docker.io/vastai/kvm) run onstart inside the guest,
    # where Vast requires an interpreter shebang (docs.vast.ai/
    # linux-virtual-machines: "the interpreter must be specified by a
    # shebang"); a ';'-joined Docker-style line is not a valid VM script.
    # VMs also need the direct SSH mapping: the proxy host does not serve
    # VMs (measured 2026-10-01: proxy refused, direct 22/tcp authenticated).
    if is_vm_image(launch_params.get('image') or image_name):
        launch_params['onstart_cmd'] = '\n'.join(['#!/bin/bash'] +
                                                 skypilot_onstart)
        launch_params['ssh'] = True
        launch_params['direct'] = True
    else:
        launch_params['onstart_cmd'] = ';'.join(skypilot_onstart)

    # Handle env - Vast.ai SDK requires env as a dict, not a CLI-style string.
    # Merge user-provided env (dict or legacy string) with skypilot metadata.
    user_env = launch_params.pop('env', None)
    env_dict: Dict[str, str] = {'__SOURCE': 'skypilot'}
    if user_env is not None:
        if isinstance(user_env, dict):
            env_dict.update(user_env)
        elif isinstance(user_env, str):
            # Parse legacy "-e KEY=VAL" style strings for backwards compat
            import re  # pylint: disable=import-outside-toplevel
            for match in re.finditer(r'-e\s+(\w+)=([^\s]*)', user_env):
                env_dict[match.group(1)] = match.group(2)
    launch_params['env'] = env_dict

    new_instance_contract = vast.vast().create_instance(**launch_params)

    new_instance = vast.vast().show_instance(
        id=new_instance_contract['new_contract'])

    return new_instance['id']


def start(instance_id: str) -> None:
    """Starts the given instance."""
    vast.vast().start_instance(id=instance_id)


def stop(instance_id: str) -> None:
    """Stops the given instance."""
    vast.vast().stop_instance(id=instance_id)


def remove(instance_id: str) -> None:
    """Terminates the given instance."""
    vast.vast().destroy_instance(id=instance_id)


def get_ssh_ports(cluster_name: str) -> List[int]:
    """Gets the SSH ports for the given cluster."""
    logger.debug(f'Getting SSH ports for cluster {cluster_name}.')

    instances = list_instances()
    possible_names = [f'{cluster_name}-head', f'{cluster_name}-worker']

    ssh_ports = []

    for instance in instances.values():
        if instance['name'] in possible_names:
            ssh_ports.append(instance['ssh_port'])
    assert ssh_ports, (
        f'Could not find any instances for cluster {cluster_name}.')

    return ssh_ports
